function addDebugObject(object,channel){object.userData.channel=channel;DebugGroup.add(object);return object}
function loadDebugObjects(bodyGroup){
 const sockets=ControlVehicleSockets.AxleMount;
 for(let i=0;i<4;i++){
  const socket=sockets[i],side=Math.sign(socket[1])||1,centerY=VehicleGeometry.TyreRadius,outerZ=socket[1]+side*.62;
  const thermalRing=new THREE.Mesh(new THREE.TorusGeometry(VehicleGeometry.TyreRadius+.055,.014,6,48),new THREE.MeshBasicMaterial({color:['#e78167','#e8be67','#72c9a2','#75aaf0'][i],transparent:true,opacity:.82,depthTest:false}));thermalRing.position.set(socket[0],centerY,outerZ);addDebugObject(thermalRing,'Thermal');
  const patch=new THREE.Mesh(new THREE.BoxGeometry(.3,.018,.2),new THREE.MeshBasicMaterial({color:'#e7b05c',transparent:true,opacity:.82,depthTest:false,depthWrite:false}));patch.position.set(socket[0],.022,outerZ);addDebugObject(patch,'Contact');
  const springPoints=[];for(let step=0;step<=32;step++){const t=step/32,angle=t*Math.PI*12;springPoints.push(new THREE.Vector3(socket[0]+Math.cos(angle)*.075,.19+t*.68,outerZ+Math.sin(angle)*.075))}const springCurve=new THREE.CatmullRomCurve3(springPoints),spring=new THREE.Mesh(new THREE.TubeGeometry(springCurve,96,.009,6,false),new THREE.MeshBasicMaterial({color:'#b39be9',depthTest:false}));addDebugObject(spring,'Suspension');const damper=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(socket[0],.17,outerZ),new THREE.Vector3(socket[0],.95,outerZ)]),new THREE.LineBasicMaterial({color:'#e2d8ff',depthTest:false}));addDebugObject(damper,'Suspension');
  const slipCenter=new THREE.Vector3(socket[0],.032,outerZ),slipRing=new THREE.Mesh(new THREE.TorusGeometry(.28,.009,5,40),new THREE.MeshBasicMaterial({color:'#75aaf0',depthTest:false}));slipRing.rotation.x=Math.PI/2;slipRing.position.copy(slipCenter);addDebugObject(slipRing,'Slip');const slipVector=new THREE.ArrowHelper(new THREE.Vector3(1,0,side*.2).normalize(),slipCenter,.4,0x75aaf0,.12,.08);slipVector.line.material.depthTest=false;slipVector.cone.material.depthTest=false;addDebugObject(slipVector,'Slip');
  const brake=new THREE.Mesh(new THREE.TorusGeometry(.2,.016,6,32),new THREE.MeshBasicMaterial({color:['#d86d58','#e29a5d','#be6a58','#d27f62'][i],depthTest:false}));brake.position.set(socket[0],centerY,outerZ+.025*side);addDebugObject(brake,'BrakeTemp');
  const load=new THREE.ArrowHelper(new THREE.Vector3(0,-1,0),new THREE.Vector3(socket[0]+.34,1.18,outerZ),.62,0xe9c46a,.15,.1);load.line.material.depthTest=false;load.cone.material.depthTest=false;addDebugObject(load,'WheelLoad');
  const ride=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(socket[0]-.34,.025,outerZ),new THREE.Vector3(socket[0]-.34,centerY,outerZ)]),new THREE.LineDashedMaterial({color:0x83c3d8,dashSize:.075,gapSize:.045,depthTest:false}));ride.computeLineDistances();addDebugObject(ride,'RideHeight');
 }
 for(const side of [-1,1]){const aero=new THREE.ArrowHelper(new THREE.Vector3(0,-1,0),new THREE.Vector3(0,1.48,side*1.72),.5,0x9bdac5,.13,.08);aero.line.material.depthTest=false;aero.cone.material.depthTest=false;addDebugObject(aero,'AeroLoad')}
 const drive=new THREE.ArrowHelper(new THREE.Vector3(1,0,0),new THREE.Vector3(-.72,.82,1.72),1.44,0xd3a6e4,.2,.12);drive.line.material.depthTest=false;drive.cone.material.depthTest=false;addDebugObject(drive,'Drivetrain');
 const normalPositions=[];bodyGroup.traverse(mesh=>{if(!mesh.isMesh)return;const p=mesh.geometry.getAttribute('position'),n=mesh.geometry.getAttribute('normal');if(!p||!n)return;const step=Math.max(1,Math.floor(p.count/100));for(let i=0;i<p.count;i+=step){const nx=n.getX(i),ny=n.getY(i),nz=n.getZ(i);if(ny<.18&&Math.abs(nz)<.72)continue;normalPositions.push(p.getX(i)+nx*.09,p.getY(i)+ny*.09,p.getZ(i)+nz*.09,p.getX(i)+nx*.22,p.getY(i)+ny*.22,p.getZ(i)+nz*.22)}});const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(normalPositions,3));addDebugObject(new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color:'#82d7b8',transparent:true,opacity:.88})),'Normals');updateDebugGeometry()
}
function updateDebugGeometry(){if(!DebugGroup)return;DebugGroup.children.forEach(object=>object.visible=object.userData.channel===state.debug);const debug=DebugChannels.find(channel=>channel.id===state.debug)||DebugChannels[0];$('#DebugLegend').hidden=false;$('#DebugLegendTitle').textContent=debug.legend;$('#DebugLegendLow').textContent=debug.range[0];$('#DebugLegendHigh').textContent=debug.range[1];$('#DebugLabel').textContent=debug.label;$('#DebugLegend').querySelector('i').style.background=debug.id==='Thermal'?'linear-gradient(90deg,#5b9fce,#69c6a4,#f1c15d,#dc705c)':debug.color}

function highlightComponent(id){if(!VehicleRoot)return;let targets=[];if(id==='Vehicle')targets=Object.values(MeshGroups);else if(id==='Tyres')targets=Object.entries(MeshGroups).filter(([key])=>key.startsWith('Wheel')).map(([,group])=>group);else{const mapped=['Cabin','Powertrain','Engine','Turbo','Transmission','Suspension'].includes(id)?'Body':id;targets=MeshGroups[mapped]?[MeshGroups[mapped]]:[]}const selectedGroups=new Set(targets);for(const group of Object.values(MeshGroups)){const selected=selectedGroups.has(group);group.traverse(object=>{if(!object.isMesh||!object.userData.baseMaterials)return;const mats=Array.isArray(object.material)?object.material:[object.material];mats.forEach((material,index)=>{const base=object.userData.baseMaterials[index]||object.userData.baseMaterials[0];material.emissive.copy(base.emissive);if(selected)material.emissive.add(new THREE.Color('#0c241c'));material.emissiveIntensity=base.emissiveIntensity||.7})})}}
async function loadVehicle(){
 const label=$('#LoadStatus');
 try{
  const folder=new URL('../../Experimental/VehicleProvingGrounds/Archive/',import.meta.url);
  const [body,tyre,rim]=await Promise.all(['ControlVehicleBody.facet','ControlVehicleTyre.facet','ControlVehicleRim.facet'].map(file=>RetrieveFacetStream(new URL(file,folder).href)));
  Streams={body,tyre,rim};
  if(!Renderer){$('#AssetLoadMeta').textContent='FACET DATA LOADED · WEBGL DISABLED';return}
  VehicleRoot=new THREE.Group();VehicleRoot.name='ControlVehicle';
  const bodyGroup=new THREE.Group();bodyGroup.userData.component='Body';MeshGroups={Body:bodyGroup};VehicleRoot.add(bodyGroup);bodyMesh(body,bodyGroup);
  for(let index=0;index<4;index++){
   const socket=ControlVehicleSockets.AxleMount[index],side=Math.sign(socket[1])||1,name=['WheelFL','WheelFR','WheelRL','WheelRR'][index],wheel=new THREE.Group();
   wheel.name=name;wheel.userData.component=name;wheel.position.set(socket[0],socket[2]+GroundOffset,socket[1]);MeshGroups[name]=wheel;VehicleRoot.add(wheel);wheelMeshes(tyre,wheel,side);wheelMeshes(rim,wheel,side,{flat:true,metalRemap:true});
  }
  Scene.add(VehicleRoot);loadDebugObjects(bodyGroup);renderUserComponents();highlightComponent(state.component);
  label.textContent=`FCT1 ASSET · ${body.FacetCount.toLocaleString()} BODY FACES · 4 WHEELS`;
  $('#AssetLoadMeta').textContent=`${body.FacetCount.toLocaleString()} body · ${tyre.FacetCount.toLocaleString()} tyre · ${rim.FacetCount.toLocaleString()} rim faces`;
  $('#SceneStats').textContent=`${body.VertexCount.toLocaleString()} BODY VERTICES · 4 WHEEL ASSEMBLIES`;
  $('#SourceStatus').style.background='#78c796';$('#VehicleWarning').hidden=true;
 }catch(error){console.error(error);label.textContent=`ASSET LOAD FAILED · ${error.message}`;$('#AssetLoadMeta').textContent='Unable to load ControlVehicle facet archives';$('#SourceStatus').style.background='#e57964';$('#VehicleWarning').hidden=false}
}
function cameraPreset(view){if(!Camera||!Controls)return;let position;if(view==='Side'){Camera.up.set(0,1,0);position=new THREE.Vector3(0,2.15,9.7)}else if(view==='Top'){Camera.up.set(0,0,-1);position=new THREE.Vector3(0,12,.01)}else{Camera.up.set(0,1,0);position=new THREE.Vector3(5.4,3.6,8.5)}Camera.position.copy(position);Controls.target.set(0,.82,0);Controls.update();state.camera=view;$$('[data-camera]').forEach(button=>button.classList.toggle('is-active',button.dataset.camera===view))}
function setCurve(name){state.curveKey=name;$$('.curve-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.curve===name));$('#CurveInterpolation').value=state.interpolation[name]||'linear';drawCurve()}
function curveSettings(){if(state.curveKey==='Torque')return{title:'Engine torque',axisY:'TORQUE · N·m',axisX:'ENGINE SPEED · RPM',xmin:0,xmax:9000,ymin:0,ymax:600,color:'#a8d8bb',desc:`${state.curves.Torque.length} authored points · peak ${Math.max(...state.curves.Torque.map(p=>p[1]))} N·m`};if(state.curveKey==='Boost')return{title:'Turbo multiplier',axisY:'TORQUE MULTIPLIER · ×',axisX:'BOOST PRESSURE · BAR',xmin:0,xmax:1.35,ymin:.8,ymax:2.1,color:'#e8c27a',desc:`${state.curves.Boost.length} authored points · ${fmt(state.values.spoolTime,2)} s spool`};return{title:'Lateral Pacejka response',axisY:'LATERAL FORCE · μ',axisX:'SLIP ANGLE · DEGREES',xmin:-18,xmax:18,ymin:-2.2,ymax:2.2,color:'#b9a3e8',desc:`MF6.1 · B ${fmt(state.values.pacejkaB,1)} · C ${fmt(PacejkaParameters.pCy1,2)} · D ${fmt(state.values.pacejkaLat,2)}`}}
function samplePacejka(){const points=[],B=state.values.pacejkaB,C=PacejkaParameters.pCy1,D=state.values.pacejkaLat,E=PacejkaParameters.pEy1;for(let i=0;i<=36;i++){const angle=-18+i,alpha=angle*Math.PI/180,x=B*alpha;points.push([angle,D*Math.sin(C*Math.atan(x-E*(x-Math.atan(x))))])}return points}
function activeCurve(){return state.curveKey==='Pacejka'?(state.curves.Pacejka.length?state.curves.Pacejka:samplePacejka()):state.curves[state.curveKey]}
function fitCurveCanvas(){const rect=CurveCanvas.getBoundingClientRect(),ratio=Math.min(2,devicePixelRatio||1),width=Math.max(1,Math.round(rect.width*ratio)),height=Math.max(1,Math.round(rect.height*ratio));if(CurveCanvas.width!==width||CurveCanvas.height!==height){CurveCanvas.width=width;CurveCanvas.height=height}CurveContext.setTransform(ratio,0,0,ratio,0,0);return{width:rect.width,height:rect.height}}
function traceCurve(ctx,points,mode){
 if(!points.length)return;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);
 for(let i=0;i<points.length-1;i++){
  const [x1,y1]=points[i],[x2,y2]=points[i+1];
  if(mode==='step'){ctx.lineTo(x2,y1);ctx.lineTo(x2,y2)}
  else if(mode==='ease')for(let sample=1;sample<=16;sample++){const t=sample/16,eased=t*t*(3-2*t);ctx.lineTo(x1+(x2-x1)*t,y1+(y2-y1)*eased)}
  else if(mode==='smooth'){const p0=points[Math.max(0,i-1)],p3=points[Math.min(points.length-1,i+2)];ctx.bezierCurveTo(x1+(x2-p0[0])/6,y1+(y2-p0[1])/6,x2-(p3[0]-x1)/6,y2-(p3[1]-y1)/6,x2,y2)}
  else ctx.lineTo(x2,y2)
 }
}
function drawCurve(){
 if(!CurveCanvas.clientWidth)return;
 const {width,height}=fitCurveCanvas(),ctx=CurveContext,spec=curveSettings(),points=activeCurve(),pad={left:9,right:11,top:12,bottom:7},plotW=width-pad.left-pad.right,plotH=height-pad.top-pad.bottom;
 CurveBounds={left:pad.left,top:pad.top,width:plotW,height:plotH,xmin:spec.xmin,xmax:spec.xmax,ymin:spec.ymin,ymax:spec.ymax};
 $('#CurveName').textContent=spec.title;$('#AxisY').textContent=spec.axisY;$('#AxisX').textContent=spec.axisX;$('#CurveDescription').textContent=spec.desc;$('#CurveInterpolation').value=state.interpolation[state.curveKey]||'linear';
 ctx.clearRect(0,0,width,height);
 const xy=point=>[pad.left+(point[0]-spec.xmin)/(spec.xmax-spec.xmin)*plotW,pad.top+(1-(point[1]-spec.ymin)/(spec.ymax-spec.ymin))*plotH];
 if(spec.ymin<0&&spec.ymax>0){ctx.strokeStyle='rgba(255,255,255,.22)';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(pad.left,xy([0,0])[1]);ctx.lineTo(width-pad.right,xy([0,0])[1]);ctx.stroke();ctx.setLineDash([])}
 const coords=points.map(xy);
 if(coords.length>1){traceCurve(ctx,coords,state.interpolation[state.curveKey]||'linear');ctx.strokeStyle=spec.color;ctx.lineWidth=2;ctx.stroke();ctx.lineTo(coords.at(-1)[0],height-pad.bottom);ctx.lineTo(coords[0][0],height-pad.bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,pad.top,0,height);gradient.addColorStop(0,spec.color+'38');gradient.addColorStop(1,spec.color+'00');ctx.fillStyle=gradient;ctx.fill()}
 for(let i=0;i<coords.length;i++){const [x,y]=coords[i];ctx.beginPath();ctx.arc(x,y,i===DragCurveIndex?5:3,0,Math.PI*2);ctx.fillStyle=i===DragCurveIndex?'#fff':spec.color;ctx.fill();ctx.strokeStyle='#101112';ctx.lineWidth=1.5;ctx.stroke()}
}

function curvePoint(event){const rect=CurveCanvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;return[CurveBounds.xmin+(x-CurveBounds.left)/CurveBounds.width*(CurveBounds.xmax-CurveBounds.xmin),CurveBounds.ymax-(y-CurveBounds.top)/CurveBounds.height*(CurveBounds.ymax-CurveBounds.ymin)]}
function saveCurveSnapshot(){CurveHistory.push({key:state.curveKey,value:(state.curves[state.curveKey]||[]).map(point=>[...point])});if(CurveHistory.length>50)CurveHistory.shift();CurveRedo.length=0}
CurveCanvas.addEventListener('pointerdown',event=>{const rect=CurveCanvas.getBoundingClientRect(),points=activeCurve();let nearest=13;DragCurveIndex=-1;points.forEach((point,index)=>{const x=CurveBounds.left+(point[0]-CurveBounds.xmin)/(CurveBounds.xmax-CurveBounds.xmin)*CurveBounds.width,y=CurveBounds.top+(1-(point[1]-CurveBounds.ymin)/(CurveBounds.ymax-CurveBounds.ymin))*CurveBounds.height,d=Math.hypot(x-(event.clientX-rect.left),y-(event.clientY-rect.top));if(d<nearest){nearest=d;DragCurveIndex=index}});if(DragCurveIndex>=0){saveCurveSnapshot();CurveCanvas.setPointerCapture(event.pointerId)}});CurveCanvas.addEventListener('pointermove',event=>{if(DragCurveIndex<0)return;const points=activeCurve(),p=curvePoint(event),spec=curveSettings();p[0]=Math.max(spec.xmin,Math.min(spec.xmax,p[0]));p[1]=Math.max(spec.ymin,Math.min(spec.ymax,p[1]));if(DragCurveIndex>0)p[0]=Math.max(p[0],points[DragCurveIndex-1][0]+.001);if(DragCurveIndex<points.length-1)p[0]=Math.min(p[0],points[DragCurveIndex+1][0]-.001);points[DragCurveIndex]=p;state.curves[state.curveKey]=points;drawCurve();persist()});CurveCanvas.addEventListener('pointerup',()=>{DragCurveIndex=-1;drawCurve()});CurveCanvas.addEventListener('dblclick',event=>{saveCurveSnapshot();const points=activeCurve(),point=curvePoint(event);points.push(point);points.sort((a,b)=>a[0]-b[0]);state.curves[state.curveKey]=points;drawCurve();persist()});
function resetCurve(){saveCurveSnapshot();state.curves[state.curveKey]=state.curveKey==='Torque'?EngineSheet.TorqueCurve.map(p=>[...p]):state.curveKey==='Boost'?TurbochargerSheet.TorqueMultiplierCurve.map(p=>[...p]):[];drawCurve();persist()}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();URL.revokeObjectURL(url)}
function resetHistory(redo,undo){const entry=redo.pop();if(!entry)return;undo.push({key:entry.key,value:(state.curves[entry.key]||[]).map(point=>[...point])});state.curves[entry.key]=entry.value;drawCurve();persist()}
function init(){installIcons();initStage();setupControls();renderUserComponents();renderInspector();syncLiveValues();setCurve('Torque');updateDebugGeometry();const resizeCurves=new ResizeObserver(()=>drawCurve());resizeCurves.observe($('.curve-chart-wrap'));loadVehicle()}
function setCamera(view){cameraPreset(view)}
init();
